import re
import sys

assignment = re.compile(
    r"^\s*(a|b|c|d|e|f|g|h|TMP)\s*<-\s*"
    r"(?:(\d+)|\(\s*\1\s*\+\s*(\d+)\s*\)\s*mod\s+100)\s*;\s*$"
)

values = {}

for line in sys.stdin:
    match = assignment.fullmatch(line)
    if not match:
        continue

    name, literal, increment = match.groups()
    if literal is not None:
        values[name] = int(literal)
    else:
        values[name] = (values[name] + int(increment)) % 100

names = ("a", "b", "c", "d", "e", "f", "g", "h", "TMP")
print(" ".join(f"{name} ?= {values[name]};" for name in names))
